/* "YYYY-MM-DD_hh:mm:ss" (UTC) -> epoch seconds, or 0. */
function tsEpoch(ts){
  var m=/^(\d{4})-(\d\d)-(\d\d)_(\d\d):(\d\d):(\d\d)$/.exec(ts||'');
  return m?Math.floor(Date.UTC(+m[1],+m[2]-1,+m[3],+m[4],+m[5],+m[6])/1000):0;}

